// Completed works live separately from the current nine-photo draft.
window.Artworks = (() => {
  function transact(mode, operation) {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open("photoMosaicGallery", 1);
      request.onupgradeneeded = () => {
        request.result.createObjectStore("works", { keyPath: "id" });
      };
      request.onerror = () => reject(request.error);
      request.onblocked = () => reject(new Error("保存先を開けませんでした。ほかのタブを閉じて再度お試しください。"));
      request.onsuccess = () => {
        const db = request.result;
        db.onversionchange = () => db.close();
        const transaction = db.transaction("works", mode);
        const result = operation(transaction.objectStore("works"));
        transaction.oncomplete = () => { db.close(); resolve(result.result); };
        transaction.onabort = () => { db.close(); reject(transaction.error); };
        transaction.onerror = () => { /* onabort handles the error. */ };
      };
    });
  }

  function loadImage(source) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error("写真を読み込めませんでした。もう一度お試しください。"));
      image.src = source;
    });
  }

  let heartMaskPromise = null;

  async function createHeartMask() {
    // Embed the unchanged guide so file:// pages can safely read its pixels.
    // External local-file images taint the canvas in some browsers.
    const guide = await loadImage("data:image/png;base64,");
    const mask = document.createElement("canvas");
    const width = mask.width = guide.naturalWidth;
    const height = mask.height = guide.naturalHeight;
    const context = mask.getContext("2d", { willReadFrequently: true });
    if (!context) throw new Error("ハートの形を読み込めませんでした。");
    context.drawImage(guide, 0, 0);
    const outline = context.getImageData(0, 0, width, height).data;
    const pixels = context.createImageData(width, height);
    const visited = new Uint8Array(width * height);
    const queue = new Int32Array(width * height);
    const center = Math.floor(height / 2) * width + Math.floor(width / 2);
    let head = 0;
    let tail = 1;
    queue[0] = center;
    visited[center] = 1;
    if (outline[center * 4 + 3] >= 128) throw new Error("ハートの内側を判定できませんでした。");
    // Fill only the transparent region enclosed by the original guide.
    // The guide's outside and its dark border are excluded from the photos.
    while (head < tail) {
      const position = queue[head++];
      const x = position % width;
      const y = Math.floor(position / width);
      if (x === 0 || y === 0 || x === width - 1 || y === height - 1) {
        throw new Error("ハートの枠が閉じていないため切り抜けませんでした。");
      }
      pixels.data[position * 4 + 3] = 255 - outline[position * 4 + 3];
      for (const next of [position - 1, position + 1, position - width, position + width]) {
        if (visited[next]) continue;
        visited[next] = 1;
        const alpha = outline[next * 4 + 3];
        if (alpha < 128) queue[tail++] = next;
        else pixels.data[next * 4 + 3] = 255 - alpha;
      }
    }
    context.putImageData(pixels, 0, 0);
    return mask;
  }

  function getHeartMask() {
    if (!heartMaskPromise) {
      heartMaskPromise = createHeartMask().catch(error => {
        heartMaskPromise = null;
        throw error;
      });
    }
    return heartMaskPromise;
  }

  async function compose(photos) {
    const mask = await getHeartMask();
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 1200;
    const context = canvas.getContext("2d");
    if (!context) throw new Error("画像を作成できませんでした。");
    context.fillStyle = "#f0f5e9";
    context.fillRect(0, 0, 1200, 1200);
    // Decode one photo at a time to avoid holding nine full camera images in memory.
    for (let index = 0; index < photos.length; index++) {
      if (!photos[index]) continue;
      let image;
      try {
        image = await loadImage(photos[index]);
      } catch (error) {
        throw new Error(`${index + 1}マス目の写真を読み込めませんでした。このマスを撮り直してお試しください。`);
      }
      // Match the centered, cover-sized photos shown in the grid.
      const side = Math.min(image.naturalWidth, image.naturalHeight);
      context.drawImage(image,
        (image.naturalWidth - side) / 2, (image.naturalHeight - side) / 2, side, side,
        (index % 3) * 400, Math.floor(index / 3) * 400, 400, 400);
      image.src = "";
    }
    context.globalCompositeOperation = "destination-in";
    context.drawImage(mask, 0, 0, canvas.width, canvas.height);
    context.globalCompositeOperation = "source-over";
    return new Promise((resolve, reject) => canvas.toBlob(
      blob => blob ? resolve(blob) : reject(new Error("画像を作成できませんでした。")),
      "image/png"));
  }

  function filename(work) {
    const extension = work.blob.type === "image/png" ? "png" : "jpg";
    return `photo-mosaic-${work.id}.${extension}`;
  }
  return {
    compose,
    filename,
    save: work => transact("readwrite", store => store.put(work)),
    remove: id => transact("readwrite", store => store.delete(id)),
    list: () => transact("readonly", store => store.getAll())
  };
})();
